        /// <summary>Set properties for diagnostics. Phone numbers are masked (<c>010****0000</c>), free text shows only its length, <c>AdditionalProperties</c> is left out.</summary>
        /// <returns>For example <c>BrandMessage(...)</c>.</returns>
        public override string ToString()
        {
            return new ModelText("BrandMessage")
                .Add("sendType", SendType)
                .Add("msgType", MsgType)
                .Add("senderKey", SenderKey)
                .Add("templateCode", TemplateCode)
                .Add("targeting", Targeting)
                .Length("text", Text)
                .Add("header", Header)
                .Add("headerDescription", HeaderDescription)
                .Length("additionalContent", AdditionalContent)
                .Add("groupTagKey", GroupTagKey)
                .Add("adult", Adult)
                .Add("pushAlarm", PushAlarm)
                .Add("adFlag", AdFlag)
                .Add("messageVariable", MessageVariable)
                .Add("buttonVariable", ButtonVariable)
                .Add("couponVariable", CouponVariable)
                .Add("imageVariable", ImageVariable)
                .Add("videoVariable", VideoVariable)
                .Add("commerceVariable", CommerceVariable)
                .Count("carouselVariable", CarouselVariable)
                .Count("catalogVariable", CatalogVariable)
                .Add("originCID", OriginCID)
                .Phone("unsubscribePhoneNumber", UnsubscribePhoneNumber)
